86	// ─── Create ────────────────────────────────────────────────────────────────────
87	
88	export async function createProjectAction(
89	  formData: FormData
90	): Promise<ActionResult<{ id: string; requestDepositPending: boolean }>> {
91	  const auth = await getAuthenticatedUser()
92	  if (!auth) return { ok: false, error: 'Not authenticated' }
93	
94	  const role = auth.role as ReadRole
95	  // Receptionist can create projects per RLS
96	  if (role === 'guest_artist') return { ok: false, error: 'Insufficient permissions' }
97	
98	  // ── Parse JSON arrays sent from the client form ──────────────────────────────
99	  function parseJsonArray(raw: FormDataEntryValue | null): string[] {
100	    if (!raw || typeof raw !== 'string' || raw === '') return []
101	    try {
102	      const parsed = JSON.parse(raw) as unknown
103	      return Array.isArray(parsed) ? (parsed as string[]) : []
104	    } catch {
105	      return []
106	    }
107	  }
108	
109	  const raw = {
110	    client_id: formData.get('client_id'),
111	    name: formData.get('name'),
112	    description: formData.get('description') || null,
113	    placement: formData.get('placement') || null,
114	    size: formData.get('size') || null,
115	    color_mode: formData.get('color_mode') || null,
116	    style_tags: parseJsonArray(formData.get('style_tags')),
117	    primary_artist_id: formData.get('primary_artist_id') || null,
118	    secondary_artist_ids: parseJsonArray(formData.get('secondary_artist_ids')),
119	    total_sessions_planned: formData.get('total_sessions_planned')
120	      ? Number(formData.get('total_sessions_planned'))
121	      : null,
122	    total_price_cents: formData.get('total_price_cents')
123	      ? Number(formData.get('total_price_cents'))
124	      : 0,
125	    initial_deposit_cents: formData.get('initial_deposit_cents')
126	      ? Number(formData.get('initial_deposit_cents'))
127	      : 0,
128	    deposit_apply_rule: formData.get('deposit_apply_rule') || 'last_session',
129	    reference_notes: formData.get('reference_notes') || null,
130	    request_deposit: formData.get('request_deposit') === 'true',
131	    request_deposit_channel:
132	      (formData.get('request_deposit_channel') as 'email' | 'sms') || 'email',
133	    moodboard_uploads: parseJsonArray(formData.get('moodboard_uploads')),
134	    moodboard_urls: parseJsonArray(formData.get('moodboard_urls')),
135	  }
136	
137	  const parsed = createProjectSchema.safeParse(raw)
138	  if (!parsed.success) {
139	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
140	  }
141	
142	  const input = parsed.data
143	  const supabase = await createClient()
144	
145	  try {
146	    // 1. Insert the project row
147	    const { data: project, error: projectErr } = await supabase
148	      .from('projects')
149	      .insert({
150	        studio_id: auth.studioId,
151	        client_id: input.client_id,
152	        name: input.name,
153	        description: input.description ?? null,
154	        placement: input.placement ?? null,
155	        size: input.size ?? null,
156	        color_mode: input.color_mode ?? null,
157	        style_tags: input.style_tags,
158	        primary_artist_id: input.primary_artist_id ?? null,
159	        secondary_artist_ids: input.secondary_artist_ids,
160	        total_sessions_planned: input.total_sessions_planned ?? null,
161	        total_price_cents: input.total_price_cents,
162	        deposit_pool_cents: input.initial_deposit_cents,
163	        deposit_applied_cents: 0,
164	        deposit_apply_rule: input.deposit_apply_rule,
165	        reference_notes: input.reference_notes ?? null,
166	        status: 'planning' as const,
167	        started_at: new Date().toISOString(),
168	      })
169	      .select('id')
170	      .single()
171	
172	    if (projectErr || !project) {
173	      logger.error({ err: projectErr, studioId: auth.studioId }, 'createProjectAction insert failed')
174	      return { ok: false, error: 'Failed to create project' }
175	    }
176	
177	    const projectId = project.id
178	
179	    // 2. Record initial deposit transaction if > 0
180	    if (input.initial_deposit_cents > 0) {
181	      // record_project_deposit is defined in migrations — not yet in generated types.
182	      // Cast through unknown to avoid TS error; safe because the server validates inputs above.
183	      const rpcFn = supabase.rpc.bind(supabase) as unknown as (
184	        fn: string,
185	        args: Record<string, unknown>
186	      ) => Promise<{ error: { message: string } | null }>
187	
188	      const { error: depositErr } = await rpcFn('record_project_deposit', {
189	        p_project_id: projectId,
190	        p_amount_cents: input.initial_deposit_cents,
191	        p_method: 'manual',
192	        p_note: 'Initial deposit recorded at project creation',
193	      })
194	      if (depositErr) {
195	        // Non-fatal — project created; log and continue
196	        logger.warn(
197	          { depositErr, projectId },
198	          'createProjectAction: record_project_deposit RPC failed (non-fatal)',
199	        )
200	      }
201	    }
202	
203	    // 3. Insert moodboard upload references
204	    if (input.moodboard_uploads.length > 0) {
205	      const uploadRows = input.moodboard_uploads.map((storagePath, i) => ({
206	        project_id: projectId,
207	        storage_path: storagePath,
208	        source: 'upload',
209	        display_order: i,
210	        created_by: auth.user.id,
211	      }))
212	      const { error: uploadRefErr } = await supabase
213	        .from('project_references' as 'projects')
214	        .insert(uploadRows as never)
215	      if (uploadRefErr) {
216	        logger.warn({ uploadRefErr, projectId }, 'createProjectAction: upload reference insert failed (non-fatal)')
217	      }
218	    }
219	
220	    // 4. Insert moodboard URL references
221	    if (input.moodboard_urls.length > 0) {
222	      const urlRows = input.moodboard_urls.map((url, i) => ({
223	        project_id: projectId,
224	        storage_path: '',
225	        source: detectUrlSource(url),
226	        external_url: url,
227	        thumbnail_url: null,
228	        display_order: (input.moodboard_uploads.length) + i,
229	        created_by: auth.user.id,
230	      }))
231	      const { error: urlRefErr } = await supabase
232	        .from('project_references' as 'projects')
233	        .insert(urlRows as never)
234	      if (urlRefErr) {
235	        logger.warn({ urlRefErr, projectId }, 'createProjectAction: url reference insert failed (non-fatal)')
236	      }
237	    }
238	
239	    // 5. Log activity
240	    const { error: logErr } = await supabase
241	      .from('project_activity_log' as 'projects')
242	      .insert({
243	        project_id: projectId,
244	        actor_id: auth.user.id,
245	        event_type: 'created',
246	        details: {
247	          name: input.name,
248	          client_id: input.client_id,
249	          initial_deposit_cents: input.initial_deposit_cents,
250	        },
251	      } as never)
252	    if (logErr) logger.warn({ logErr, projectId }, 'createProjectAction: activity log failed (non-fatal)')
253	
254	    revalidatePath('/projects')
255	
256	    return {
257	      ok: true,
258	      data: { id: projectId, requestDepositPending: input.request_deposit },
259	    }
260	  } catch (err) {
261	    logger.error({ err }, 'createProjectAction failed')
262	    return { ok: false, error: 'Failed to create project' }
263	  }
264	}
