266	// ─── Update ────────────────────────────────────────────────────────────────────
267	
268	export async function updateProjectAction(
269	  id: string,
270	  formData: FormData
271	): Promise<ActionResult<void>> {
272	  const auth = await getAuthenticatedUser()
273	  if (!auth) return { ok: false, error: 'Not authenticated' }
274	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
275	
276	  const raw = {
277	    name: formData.get('name') || undefined,
278	    description: formData.get('description') ?? undefined,
279	    placement: formData.get('placement') ?? undefined,
280	    style: formData.get('style') ?? undefined,
281	    primaryArtistId: formData.get('primaryArtistId') ?? undefined,
282	    totalSessionsPlanned: formData.get('totalSessionsPlanned')
283	      ? Number(formData.get('totalSessionsPlanned'))
284	      : undefined,
285	    totalPriceCents: formData.get('totalPriceCents')
286	      ? Number(formData.get('totalPriceCents'))
287	      : undefined,
288	    moodboardUrl: formData.get('moodboardUrl') ?? undefined,
289	    status: formData.get('status') ?? undefined,
290	  }
291	
292	  const parsed = projectUpdateSchema.safeParse(raw)
293	  if (!parsed.success) {
294	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
295	  }
296	
297	  try {
298	    await updateProject(auth.studioId, id, parsed.data)
299	    revalidatePath('/projects')
300	    revalidatePath(`/projects/${id}`)
301	    return { ok: true, data: undefined }
302	  } catch (err) {
303	    logger.error({ err, id }, 'updateProjectAction failed')
304	    return { ok: false, error: 'Failed to update project' }
305	  }
306	}
