import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { createPaymentCheckout } from '@/lib/dodo/checkout'

export const dynamic = 'force-dynamic'

const bodySchema = z.object({
  amount_cents: z.number().int().min(100, 'Minimum deposit is $1.00'),
  channel: z.enum(['email', 'sms', 'link']).optional().default('link'),
})

/**
 * POST /api/projects/[id]/deposits/checkout
 * Creates a Dodo one-time payment checkout for a project deposit.
 * Returns { checkoutUrl } to redirect or send the client.
 */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  // Role check: owner/admin/receptionist only (not artist or guest_artist)
  const role = auth.role
  if (role === 'guest_artist' || role === 'artist') {
    return NextResponse.json({ error: 'insufficient permissions' }, { status: 403 })
  }

  const { id: projectId } = await params

  let body: z.infer<typeof bodySchema>
  try {
    const raw = await req.json() as unknown
    const parsed = bodySchema.safeParse(raw)
    if (!parsed.success) {
      return NextResponse.json(
        { error: parsed.error.issues[0]?.message ?? 'Invalid request body' },
        { status: 400 }
      )
    }
    body = parsed.data
  } catch {
    return NextResponse.json({ error: 'invalid json' }, { status: 400 })
  }

  const supabase = await createClient()

  // Fetch project + client + studio — all scoped to user's studio (RLS-enforced)
  const { data: project } = await supabase
    .from('projects')
    .select(`
      id, studio_id, client_id, name, status,
      client:clients!projects_client_id_fkey(
        id, email, first_name, last_name, phone
      )
    `)
    .eq('id', projectId)
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!project) {
    return NextResponse.json({ error: 'project not found' }, { status: 404 })
  }

  // Fetch studio for country + branding
  const { data: studio } = await supabase
    .from('studios')
    .select('id, name, country_iso2')
    .eq('id', auth.studioId)
    .maybeSingle()

  if (!studio) {
    return NextResponse.json({ error: 'studio not found' }, { status: 404 })
  }

  // Get Dodo customer ID from subscription if available
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('dodo_customer_id')
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  const productId =
    process.env.DODO_PRODUCT_PROJECT_DEPOSIT ??
    process.env.DODO_PRODUCT_BALANCE_COLLECTION ??
    ''
  if (!productId) {
    return NextResponse.json({ error: 'deposit product not configured' }, { status: 500 })
  }

  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
  const returnUrl = `${appUrl}/projects/${projectId}?deposit=success`

  // Resolve client details — handle both array and object shapes from PostgREST joins
  type ClientJoin = {
    id: string
    email: string | null
    first_name: string
    last_name: string | null
    phone: string | null
  }
  const clientRaw = project.client
  const client: ClientJoin | null = Array.isArray(clientRaw)
    ? (clientRaw[0] ?? null)
    : (clientRaw ?? null)

  const clientEmail = client?.email ?? ''
  const clientName = [client?.first_name, client?.last_name].filter(Boolean).join(' ')
  const billingCountry = studio.country_iso2 ?? 'US'

  try {
    const result = await createPaymentCheckout({
      productId,
      amountCents: body.amount_cents,
      currency: 'USD',
      customerId: sub?.dodo_customer_id ?? undefined,
      customerEmail: clientEmail,
      returnUrl,
      metadata: {
        type: 'project_deposit',
        project_id: projectId,
        studio_id: auth.studioId,
        amount_cents: String(body.amount_cents),
        billing_country: billingCountry,
        client_name: clientName,
      },
      description: `Deposit for ${project.name ?? 'project'}`,
    })

    await logAuditAction(
      auth.user.authId,
      'project.deposit.checkout_created',
      { type: 'project', id: projectId },
      { amountCents: body.amount_cents, channel: body.channel, checkoutId: result.checkoutId },
      auth.studioId
    )

    // Sprint 6 will wire full email/SMS delivery via job queue.
    // For now, log the channel intent and return the URL.
    if (body.channel === 'email' || body.channel === 'sms') {
      logger.info(
        { projectId, channel: body.channel, checkoutUrl: result.checkoutUrl },
        'project deposit checkout: delivery channel stub — Sprint 6 wires full send'
      )
    }

    return NextResponse.json({ checkoutUrl: result.checkoutUrl, checkoutId: result.checkoutId })
  } catch (err) {
    logger.error({ err, projectId, studioId: auth.studioId }, 'project deposit checkout creation failed')
    return NextResponse.json({ error: 'failed to create deposit checkout' }, { status: 500 })
  }
}

import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { getDodoClient } from '@/lib/dodo/client'

export const dynamic = 'force-dynamic'

const bodySchema = z.object({
  amount_cents: z.number().int().positive().optional(),
  reason: z.string().min(1, 'Reason is required').max(500),
})

/**
 * POST /api/projects/[id]/deposits/[txId]/refund
 * Refunds a specific project deposit transaction.
 * Owner/admin only. Calls Dodo refund API if the transaction has an external_id.
 * Commits via refund_project_deposit RPC.
 */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string; txId: string }> }
) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  // Role check: owner/admin only
  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'only owners and admins can refund deposits' }, { status: 403 })
  }

  const { id: projectId, txId } = await params

  let body: z.infer<typeof bodySchema>
  try {
    const raw = await req.json() as unknown
    const parsed = bodySchema.safeParse(raw)
    if (!parsed.success) {
      return NextResponse.json(
        { error: parsed.error.issues[0]?.message ?? 'Invalid request body' },
        { status: 400 }
      )
    }
    body = parsed.data
  } catch {
    return NextResponse.json({ error: 'invalid json' }, { status: 400 })
  }

  const supabase = await createClient()

  // Verify project belongs to this studio (RLS-enforced via session client)
  const { data: project } = await supabase
    .from('projects')
    .select('id, studio_id, deposit_pool_cents, deposit_applied_cents')
    .eq('id', projectId)
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!project) {
    return NextResponse.json({ error: 'project not found' }, { status: 404 })
  }

  // Fetch the specific transaction — must be type='received' and belong to this project
  const { data: txRow } = await supabase
    .from('project_deposit_transactions' as 'projects')
    .select('*' as never)
    .eq('id' as never, txId)
    .eq('project_id' as never, projectId)
    .eq('type' as never, 'received')
    .maybeSingle()

  if (!txRow) {
    return NextResponse.json({ error: 'transaction not found or not refundable' }, { status: 404 })
  }

  // txRow is typed as unknown due to cast; assert the shape we need
  const tx = txRow as unknown as {
    id: string
    project_id: string
    type: string
    amount_cents: number
    external_id: string | null
  }

  // Default to the original transaction amount if not specified
  const refundCents = body.amount_cents ?? tx.amount_cents

  // Pool balance guard
  const poolBalance = Math.max(0, project.deposit_pool_cents - project.deposit_applied_cents)
  if (refundCents > poolBalance) {
    return NextResponse.json(
      { error: `Refund amount (${refundCents}) exceeds available pool balance (${poolBalance})` },
      { status: 409 }
    )
  }

  let externalRefundId: string | null = null

  // Attempt Dodo refund if the original payment has an external ID
  if (tx.external_id) {
    try {
      const dodoClient = getDodoClient()
      // Dodo refund API: POST /payments/{id}/refund
      const refundResult = await (dodoClient.payments as unknown as {
        refund: (id: string, opts: { amount: number }) => Promise<{ id?: string }>
      }).refund(tx.external_id, { amount: refundCents })
      externalRefundId = refundResult?.id ?? null
    } catch (err) {
      logger.error({ err, txId, projectId }, 'project deposit: Dodo refund API call failed')
      return NextResponse.json({ error: 'Dodo refund failed — please retry' }, { status: 502 })
    }
  }

  // Use service-role client for RPC write (bypasses RLS for audit-critical path)
  const srClient = createServiceRoleClient()

  type RefundRpcResult = { data: string | null; error: { message: string } | null }

  const rpcFn = srClient.rpc.bind(srClient) as unknown as (
    fn: string,
    args: Record<string, unknown>
  ) => Promise<RefundRpcResult>

  const { data: newTxId, error: rpcErr } = await rpcFn('refund_project_deposit', {
    p_project_id: projectId,
    p_amount_cents: refundCents,
    p_external_refund_id: externalRefundId,
    p_note: body.reason,
  })

  if (rpcErr) {
    logger.error({ rpcErr, projectId, txId }, 'refund_project_deposit RPC failed')
    return NextResponse.json({ error: 'Failed to record refund' }, { status: 500 })
  }

  await logAuditAction(
    auth.user.authId,
    'project.deposit.refunded',
    { type: 'project', id: projectId },
    { originalTxId: txId, newTxId, refundCents, externalRefundId, reason: body.reason },
    auth.studioId
  )

  return NextResponse.json({ transaction_id: newTxId })
}

import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, createServiceRoleClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { randomUUID } from 'crypto'

export const dynamic = 'force-dynamic'

const ALLOWED_MIME_TYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/heic',
  'image/heif',
])

const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024 // 10 MB

const querySchema = z.object({
  project_id: z.string().uuid('project_id must be a valid UUID'),
})

/**
 * POST /api/projects/upload-reference
 * Uploads a single reference image to `project-references` Supabase Storage.
 * Accepts multipart/form-data with `project_id` + `file`.
 * Call once per file from the client; chain calls for multiple files.
 *
 * Role: studio member (not guest_artist).
 * Returns { uploaded: [{ id, storage_path, public_url }] }
 */
export async function POST(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  // Role check: not guest_artist
  if (auth.role === 'guest_artist') {
    return NextResponse.json({ error: 'insufficient permissions' }, { status: 403 })
  }

  let formData: FormData
  try {
    formData = await req.formData()
  } catch {
    return NextResponse.json({ error: 'invalid multipart body' }, { status: 400 })
  }

  // Parse and validate project_id
  const projectIdRaw = formData.get('project_id')
  const queryParsed = querySchema.safeParse({ project_id: projectIdRaw })
  if (!queryParsed.success) {
    return NextResponse.json(
      { error: queryParsed.error.issues[0]?.message ?? 'project_id is required' },
      { status: 400 }
    )
  }
  const { project_id: projectId } = queryParsed.data

  // Verify project belongs to this studio (RLS-enforced via session client)
  const supabase = await createClient()
  const { data: project } = await supabase
    .from('projects')
    .select('id, studio_id')
    .eq('id', projectId)
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!project) {
    return NextResponse.json({ error: 'project not found' }, { status: 404 })
  }

  // Resolve the file
  const fileValue = formData.get('file')
  if (!fileValue || !(fileValue instanceof File)) {
    return NextResponse.json({ error: 'file is required' }, { status: 400 })
  }
  const file = fileValue

  // Validate MIME type
  if (!ALLOWED_MIME_TYPES.has(file.type)) {
    return NextResponse.json(
      { error: `Unsupported file type: ${file.type}. Allowed: JPEG, PNG, WebP, HEIC.` },
      { status: 415 }
    )
  }

  // Validate file size
  if (file.size > MAX_FILE_SIZE_BYTES) {
    return NextResponse.json(
      { error: `File exceeds 10 MB limit (got ${(file.size / 1024 / 1024).toFixed(1)} MB)` },
      { status: 413 }
    )
  }

  // Determine extension — fall back to mime subtype
  const mimeToExt: Record<string, string> = {
    'image/jpeg': 'jpg',
    'image/png': 'png',
    'image/webp': 'webp',
    'image/heic': 'heic',
    'image/heif': 'heic',
  }
  const ext = mimeToExt[file.type] ?? 'jpg'
  const filename = `ref_${randomUUID()}.${ext}`
  const storagePath = `${auth.studioId}/${projectId}/${filename}`

  // Upload via service-role client — bypasses Storage RLS
  const srClient = createServiceRoleClient()
  const arrayBuffer = await file.arrayBuffer()
  const fileBuffer = Buffer.from(arrayBuffer)

  const { error: uploadError } = await srClient.storage
    .from('project-references')
    .upload(storagePath, fileBuffer, {
      contentType: file.type,
      upsert: false,
    })

  if (uploadError) {
    logger.error({ uploadError, projectId, storagePath }, 'upload-reference: storage upload failed')
    return NextResponse.json({ error: 'Failed to upload file' }, { status: 500 })
  }

  // Get public URL
  const { data: publicData } = srClient.storage
    .from('project-references')
    .getPublicUrl(storagePath)
  const publicUrl = publicData?.publicUrl ?? ''

  // Determine display_order = max existing + 1
  const { data: maxOrderRow } = await supabase
    .from('project_references')
    .select('display_order')
    .eq('project_id', projectId)
    .order('display_order', { ascending: false })
    .limit(1)
    .maybeSingle()

  const displayOrder = ((maxOrderRow as { display_order: number | null } | null)?.display_order ?? -1) + 1

  // Insert project_references row
  const { data: refRow, error: insertError } = await supabase
    .from('project_references')
    .insert({
      project_id: projectId,
      storage_path: storagePath,
      source: 'upload',
      display_order: displayOrder,
      created_by: auth.user.id,
    } as never)
    .select('id, storage_path')
    .single()

  if (insertError || !refRow) {
    logger.error({ insertError, projectId, storagePath }, 'upload-reference: reference row insert failed')
    // Best-effort: delete orphaned file
    await srClient.storage.from('project-references').remove([storagePath]).catch(() => undefined)
    return NextResponse.json({ error: 'Failed to save reference record' }, { status: 500 })
  }

  const row = refRow as unknown as { id: string; storage_path: string }

  // Log activity (best-effort)
  await supabase
    .from('project_activity_log' as 'projects')
    .insert({
      project_id: projectId,
      actor_id: auth.user.id,
      event_type: 'reference_added',
      details: { storage_path: storagePath, source: 'upload' },
    } as never)
    .catch(() => undefined)

  return NextResponse.json({
    uploaded: [
      {
        id: row.id,
        storage_path: row.storage_path,
        public_url: publicUrl,
      },
    ],
  })
}

