'use client'

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import {
  Plus,
  MoreHorizontal,
  Loader2,
  Copy,
  ExternalLink,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { MoneyInput } from '@/components/ui/money-input'
import { Label } from '@/components/ui/label'
import { Input } from '@/components/ui/input'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { cn, formatCurrency, formatDate } from '@/lib/utils'
import {
  recordManualDepositAction,
  applyDepositToSessionAction,
  consumeDepositAction,
  refundDepositAction,
} from '@/app/(app)/projects/actions'
import type { ProjectDepositTransactionRow } from '@/lib/projects/queries'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface DepositPoolSummary {
  paid_cents: number
  applied_cents: number
  remaining_cents: number
  /** Numeric session number this deposit will auto-apply to, or null if not set */
  applies_to_session: number | null
}

export interface DepositPoolSession {
  id: string
  session_number: number | null
  scheduled_at: string
}

export interface DepositPoolLedgerProps {
  projectId: string
  pool: DepositPoolSummary
  transactions: ProjectDepositTransactionRow[]
  sessions?: DepositPoolSession[]
  canManage: boolean
  /** Compact mode: hide header + padding; used in sidebar embed */
  compact?: boolean
  onRefresh?: () => void
}

// ─── Transaction row ───────────────────────────────────────────────────────────

function TxRow({
  tx,
  sessionNumber,
}: {
  tx: ProjectDepositTransactionRow
  sessionNumber: number | null
}) {
  const isCredit = tx.type === 'received'
  const isNote = tx.type === 'applied'
  const isDebit = tx.type === 'refunded' || tx.type === 'consumed'

  let description = ''
  if (tx.type === 'received') {
    const method = tx.method ? ` via ${tx.method}` : ''
    description = `Deposit received${method}`
  } else if (tx.type === 'applied') {
    const sn = sessionNumber != null ? `S${sessionNumber}` : 'session'
    description = `Applied to ${sn}`
  } else if (tx.type === 'refunded') {
    description = 'Refunded to client'
  } else if (tx.type === 'consumed') {
    description = tx.note ? `No-show write-off · ${tx.note}` : 'No-show write-off'
  }

  const amountStr = formatCurrency(tx.amount_cents)
  const dateStr = formatDate(tx.created_at, { month: 'short', day: 'numeric' })

  return (
    <div className="flex items-start gap-3 py-2.5 border-b border-white/10 last:border-0">
      <div className="flex-1 min-w-0">
        <p className="text-[11px] text-[var(--color-stone)]">{dateStr}</p>
        <p className="text-sm italic text-[var(--color-bone)] truncate">{description}</p>
        {tx.note && tx.type !== 'consumed' && (
          <p className="text-[11px] text-[var(--color-stone)] truncate">{tx.note}</p>
        )}
      </div>
      <span
        className={cn(
          'text-sm font-semibold tabular-nums shrink-0 mt-0.5',
          isCredit && 'text-emerald-400',
          isNote && 'text-[var(--color-stone)]',
          isDebit && 'text-[var(--color-rust)]'
        )}
      >
        {isCredit ? '+' : isNote ? '−' : '−'}{amountStr}
      </span>
    </div>
  )
}

// ─── Main ledger ──────────────────────────────────────────────────────────────

export function DepositPoolLedger({
  projectId,
  pool,
  transactions,
  sessions = [],
  canManage,
  compact = false,
  onRefresh,
}: DepositPoolLedgerProps) {
  const [isPending, startTransition] = useTransition()

  // Dialog visibility
  const [showRecordDialog, setShowRecordDialog] = useState(false)
  const [showLinkDialog, setShowLinkDialog] = useState(false)
  const [showApplyDialog, setShowApplyDialog] = useState(false)
  const [showConsumeDialog, setShowConsumeDialog] = useState(false)
  const [showRefundDialog, setShowRefundDialog] = useState(false)

  // Record manual deposit form
  const [recordMethod, setRecordMethod] = useState<'cash' | 'card' | 'other'>('cash')
  const [recordAmount, setRecordAmount] = useState(0)
  const [recordNote, setRecordNote] = useState('')

  // Dodo link generation
  const [linkAmount, setLinkAmount] = useState(0)
  const [generatedLink, setGeneratedLink] = useState<string | null>(null)
  const [isGeneratingLink, setIsGeneratingLink] = useState(false)

  // Apply dialog
  const [applyBookingId, setApplyBookingId] = useState('')
  const [applyAmount, setApplyAmount] = useState(0)

  // Consume dialog
  const [consumeNote, setConsumeNote] = useState('')

  // Refund dialog
  const [refundAmount, setRefundAmount] = useState(pool.remaining_cents)

  // Sessions not yet applied to
  const appliedSessionIds = new Set(
    transactions
      .filter((t) => t.type === 'applied' && t.applied_to_session_id)
      .map((t) => t.applied_to_session_id)
  )
  const availableSessions = sessions.filter((s) => !appliedSessionIds.has(s.id))

  // Session number lookup for tx rows
  const sessionNumberById = Object.fromEntries(
    sessions.map((s) => [s.id, s.session_number ?? null])
  ) as Record<string, number | null>

  // Sort transactions chronologically (oldest first)
  const sortedTx = [...transactions].sort(
    (a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
  )

  // ── Handlers ────────────────────────────────────────────────────────────────

  const handleGenerateLink = async () => {
    if (linkAmount < 100) { toast.error('Minimum deposit is $1.00'); return }
    setIsGeneratingLink(true)
    try {
      const res = await fetch(`/api/projects/${projectId}/deposits/checkout`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ amount_cents: linkAmount, channel: 'link' }),
      })
      const json = await res.json() as { checkoutUrl?: string; error?: string }
      if (!res.ok || !json.checkoutUrl) {
        toast.error(json.error ?? 'Failed to generate checkout link')
        return
      }
      setGeneratedLink(json.checkoutUrl)
    } catch {
      toast.error('Network error — please retry')
    } finally {
      setIsGeneratingLink(false)
    }
  }

  const handleCopyLink = async () => {
    if (!generatedLink) return
    await navigator.clipboard.writeText(generatedLink).catch(() => undefined)
    toast.success('Link copied')
  }

  const handleRecordManual = () => {
    if (recordAmount <= 0) { toast.error('Amount must be greater than zero'); return }
    startTransition(async () => {
      const result = await recordManualDepositAction({
        project_id: projectId,
        amount_cents: recordAmount,
        method: recordMethod,
        note: recordNote.trim() || undefined,
      })
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Deposit recorded')
      setShowRecordDialog(false)
      setRecordAmount(0)
      setRecordNote('')
      onRefresh?.()
    })
  }

  const handleApply = () => {
    if (!applyBookingId) { toast.error('Select a session'); return }
    if (applyAmount <= 0) { toast.error('Amount must be greater than zero'); return }
    if (applyAmount > pool.remaining_cents) { toast.error('Amount exceeds available balance'); return }
    startTransition(async () => {
      const result = await applyDepositToSessionAction({
        project_id: projectId,
        booking_id: applyBookingId,
        amount_cents: applyAmount,
      })
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Deposit applied to session')
      setShowApplyDialog(false)
      setApplyBookingId('')
      setApplyAmount(0)
      onRefresh?.()
    })
  }

  const handleConsume = () => {
    startTransition(async () => {
      const result = await consumeDepositAction({
        project_id: projectId,
        reason: consumeNote.trim() || undefined,
      })
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Deposit written off')
      setShowConsumeDialog(false)
      setConsumeNote('')
      onRefresh?.()
    })
  }

  const handleRefund = () => {
    if (refundAmount <= 0) { toast.error('Amount must be greater than zero'); return }
    if (refundAmount > pool.remaining_cents) { toast.error('Amount exceeds available balance'); return }
    startTransition(async () => {
      const result = await refundDepositAction({
        project_id: projectId,
        amount_cents: refundAmount,
        reason: 'Refund requested by studio',
      })
      if (!result.ok) { toast.error(result.error); return }
      toast.success('Refund recorded')
      setShowRefundDialog(false)
      setRefundAmount(0)
      onRefresh?.()
    })
  }

  // ── Render ────────────────────────────────────────────────────────────────────

  const applyLabel = pool.applies_to_session != null ? `S${pool.applies_to_session}` : null

  return (
    <div
      className={cn(
        'rounded-xl bg-[var(--color-onyx)] text-[var(--color-bone)] shadow-[var(--shadow-card)]',
        compact ? 'p-3' : 'p-5 space-y-4'
      )}
      data-testid="deposit-pool-ledger"
    >
      {/* ── Header ────────────────────────────────────────────────────────── */}
      {!compact && (
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-stone)]">
            Deposit Pool
          </span>
          {canManage && pool.remaining_cents > 0 && (
            <DropdownMenu>
              <DropdownMenuTrigger
                render={
                  <button
                    className="p-1 rounded hover:bg-white/10 text-[var(--color-stone)] hover:text-[var(--color-bone)] transition-colors"
                    aria-label="Deposit options"
                  >
                    <MoreHorizontal className="h-4 w-4" />
                  </button>
                }
              />
              <DropdownMenuContent align="end" className="w-44">
                {availableSessions.length > 0 && (
                  <DropdownMenuItem onClick={() => setShowApplyDialog(true)}>
                    Apply to session
                  </DropdownMenuItem>
                )}
                <DropdownMenuItem onClick={() => { setRefundAmount(pool.remaining_cents); setShowRefundDialog(true) }}>
                  Refund
                </DropdownMenuItem>
                <DropdownMenuItem
                  className="text-[var(--color-rust)] focus:text-[var(--color-rust)]"
                  onClick={() => setShowConsumeDialog(true)}
                >
                  Write off (no-show)
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          )}
        </div>
      )}

      {/* ── Big balance number ────────────────────────────────────────────── */}
      <div className={compact ? 'mb-2' : undefined}>
        <div className="font-serif italic text-4xl tabular-nums text-[var(--color-bone)] leading-none">
          {formatCurrency(pool.remaining_cents)}
        </div>
        <p className="text-[11px] text-[var(--color-stone)] mt-1 leading-relaxed">
          {formatCurrency(pool.paid_cents)} paid &middot;{' '}
          {formatCurrency(pool.applied_cents)} applied
          {applyLabel ? ` · applies to ${applyLabel}` : ''}
        </p>
      </div>

      {/* ── Transaction log ───────────────────────────────────────────────── */}
      {sortedTx.length > 0 && (
        <div
          className={cn(
            'border-t border-white/10 pt-3',
            compact ? 'max-h-36 overflow-y-auto' : 'max-h-52 overflow-y-auto'
          )}
        >
          {sortedTx.map((tx) => (
            <TxRow
              key={tx.id}
              tx={tx}
              sessionNumber={
                tx.applied_to_session_id != null
                  ? (sessionNumberById[tx.applied_to_session_id] ?? null)
                  : null
              }
            />
          ))}
        </div>
      )}

      {/* ── Actions footer ────────────────────────────────────────────────── */}
      {canManage && (
        <div className={cn('flex gap-2 flex-wrap', compact ? 'pt-2 border-t border-white/10' : undefined)}>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setShowRecordDialog(true)}
            className="bg-white/10 hover:bg-white/20 text-[var(--color-bone)] border-0 gap-1.5"
          >
            <Plus className="h-3.5 w-3.5" />
            Record payment
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => { setGeneratedLink(null); setLinkAmount(0); setShowLinkDialog(true) }}
            className="bg-white/10 hover:bg-white/20 text-[var(--color-bone)] border-0 gap-1.5"
          >
            <ExternalLink className="h-3.5 w-3.5" />
            Send link
          </Button>
          {pool.remaining_cents > 0 && availableSessions.length > 0 && (
            <Button
              size="sm"
              variant="outline"
              onClick={() => setShowApplyDialog(true)}
              className="bg-white/10 hover:bg-white/20 text-[var(--color-bone)] border-0"
            >
              Apply now
            </Button>
          )}
        </div>
      )}

      {/* ── Record manual deposit dialog ─────────────────────────────────── */}
      <Dialog open={showRecordDialog} onOpenChange={setShowRecordDialog}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>Record payment</DialogTitle>
            <DialogDescription>Add a received cash or card payment to the pool.</DialogDescription>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="space-y-1.5">
              <Label>Method</Label>
              <Select value={recordMethod} onValueChange={(v) => { if (v) setRecordMethod(v as typeof recordMethod) }}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="cash">Cash</SelectItem>
                  <SelectItem value="card">Card terminal</SelectItem>
                  <SelectItem value="other">Other</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Amount</Label>
              <MoneyInput value={recordAmount} onValueChange={(v) => setRecordAmount(v ?? 0)} placeholder="0.00" />
            </div>
            <div className="space-y-1.5">
              <Label>Note (optional)</Label>
              <Input
                value={recordNote}
                onChange={(e) => setRecordNote(e.target.value)}
                placeholder="e.g. Venmo transfer"
                maxLength={200}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowRecordDialog(false)}>Cancel</Button>
            <Button onClick={handleRecordManual} disabled={isPending}>
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Record
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Send checkout link dialog ────────────────────────────────────── */}
      <Dialog open={showLinkDialog} onOpenChange={(open) => { setShowLinkDialog(open); if (!open) setGeneratedLink(null) }}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>Send deposit link</DialogTitle>
            <DialogDescription>
              Generate a Dodo Payments checkout link to send to your client.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="space-y-1.5">
              <Label>Amount</Label>
              <MoneyInput value={linkAmount} onValueChange={(v) => setLinkAmount(v ?? 0)} placeholder="0.00" />
            </div>
            {generatedLink && (
              <div className="space-y-1.5">
                <Label>Checkout link</Label>
                <div className="flex items-center gap-2">
                  <Input
                    readOnly
                    value={generatedLink}
                    className="text-xs font-mono truncate"
                  />
                  <Button size="sm" variant="outline" onClick={handleCopyLink} className="shrink-0">
                    <Copy className="h-3.5 w-3.5" />
                  </Button>
                </div>
                <p className="text-[11px] text-[var(--color-stone)]">
                  Share this link with your client. Payment is automatically recorded when they complete checkout.
                </p>
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowLinkDialog(false)}>Close</Button>
            {!generatedLink ? (
              <Button onClick={handleGenerateLink} disabled={isGeneratingLink || linkAmount < 100}>
                {isGeneratingLink && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                Generate link
              </Button>
            ) : (
              <Button asChild variant="outline">
                <a href={generatedLink} target="_blank" rel="noopener noreferrer">
                  Open <ExternalLink className="ml-1.5 h-3 w-3" />
                </a>
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Apply to session dialog ──────────────────────────────────────── */}
      <Dialog open={showApplyDialog} onOpenChange={setShowApplyDialog}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>Apply deposit to session</DialogTitle>
            <DialogDescription>
              {formatCurrency(pool.remaining_cents)} available.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="space-y-1.5">
              <Label>Session</Label>
              <Select value={applyBookingId} onValueChange={(v) => { if (v) setApplyBookingId(v) }}>
                <SelectTrigger><SelectValue placeholder="Select session…" /></SelectTrigger>
                <SelectContent>
                  {availableSessions.map((s) => (
                    <SelectItem key={s.id} value={s.id}>
                      Session {s.session_number ?? '—'} &middot; {formatDate(s.scheduled_at, { month: 'short', day: 'numeric' })}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label>Amount</Label>
              <MoneyInput value={applyAmount} onValueChange={(v) => setApplyAmount(v ?? 0)} placeholder="0.00" />
              <p className="text-xs text-[var(--color-stone)]">Max: {formatCurrency(pool.remaining_cents)}</p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowApplyDialog(false)}>Cancel</Button>
            <Button onClick={handleApply} disabled={isPending}>
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Apply
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Consume (write-off) dialog ───────────────────────────────────── */}
      <Dialog open={showConsumeDialog} onOpenChange={setShowConsumeDialog}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>Write off deposit</DialogTitle>
            <DialogDescription>
              Zeros out the {formatCurrency(pool.remaining_cents)} balance. Use for no-shows or forfeitures.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-1.5 py-2">
            <Label>Note (optional)</Label>
            <Input
              value={consumeNote}
              onChange={(e) => setConsumeNote(e.target.value)}
              placeholder="e.g. No-show — Apr 28"
              maxLength={200}
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowConsumeDialog(false)}>Cancel</Button>
            <Button
              onClick={handleConsume}
              disabled={isPending}
              className="bg-[var(--color-destructive)] text-[var(--color-destructive-foreground)] hover:bg-[var(--color-destructive)]/90"
            >
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Write off
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ── Refund dialog ────────────────────────────────────────────────── */}
      <Dialog open={showRefundDialog} onOpenChange={setShowRefundDialog}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>Record refund</DialogTitle>
            <DialogDescription>
              {formatCurrency(pool.remaining_cents)} available to refund.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-1.5 py-2">
            <Label>Amount</Label>
            <MoneyInput value={refundAmount} onValueChange={(v) => setRefundAmount(v ?? 0)} placeholder="0.00" />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowRefundDialog(false)}>Cancel</Button>
            <Button onClick={handleRefund} disabled={isPending}>
              {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Record refund
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

