// ─── Sprint 5: RPC-backed deposit actions ────────────────────────────────────
// These replace the direct-insert actions above and route through the
// SECURITY DEFINER RPCs defined in 20260430100100_projects_v1_rpcs.sql.
// The old recordDepositTransactionAction / applyDepositToSessionAction remain
// for backwards compatibility with existing callers; these new exports are the
// canonical Sprint 5 surface used by DepositPoolLedger.

const recordManualDepositSchema = z.object({
  project_id: z.string().uuid(),
  amount_cents: z.number().int().positive().max(1_000_000_00, 'Amount exceeds the $1M cap'),
  method: z.enum(['cash', 'card', 'other']).optional(),
  note: z.string().max(500).optional(),
})

export async function recordManualDepositAction(
  input: z.infer<typeof recordManualDepositSchema>
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }

  const role = auth.role as ReadRole
  if (role !== 'owner' && role !== 'admin' && role !== 'receptionist') {
    return { ok: false, error: 'Only owners, admins, and receptionists can record deposits' }
  }

  const parsed = recordManualDepositSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  const supabase = await createClient()
  const scopeCheck = await verifyProjectInStudio(supabase, auth.studioId, parsed.data.project_id)
  if (!scopeCheck.ok) return scopeCheck

  type RpcResult = { data: string | null; error: { message: string } | null }
  const rpcFn = supabase.rpc.bind(supabase) as unknown as (
    fn: string,
    args: Record<string, unknown>
  ) => Promise<RpcResult>

  const { error: rpcErr } = await rpcFn('record_project_deposit', {
    p_project_id: parsed.data.project_id,
    p_amount_cents: parsed.data.amount_cents,
    p_method: parsed.data.method ?? 'manual',
    p_external_id: null,
    p_note: parsed.data.note ?? null,
  })

  if (rpcErr) {
    logger.error({ rpcErr, projectId: parsed.data.project_id }, 'recordManualDepositAction RPC failed')
    return { ok: false, error: 'Failed to record deposit' }
  }

  revalidatePath(`/projects/${parsed.data.project_id}`)
  return { ok: true, data: undefined }
}

const applyDepositToSessionInputSchema = z.object({
  project_id: z.string().uuid(),
  booking_id: z.string().uuid(),
  amount_cents: z.number().int().positive().max(1_000_000_00, 'Amount exceeds the $1M cap'),
})

export async function applyDepositToSessionAction(
  input: z.infer<typeof applyDepositToSessionInputSchema>
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }

  const role = auth.role as ReadRole
  if (role !== 'owner' && role !== 'admin' && role !== 'receptionist') {
    return { ok: false, error: 'Only owners, admins, and receptionists can apply deposits' }
  }

  const parsed = applyDepositToSessionInputSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  const supabase = await createClient()
  const scopeCheck = await verifyProjectInStudio(supabase, auth.studioId, parsed.data.project_id)
  if (!scopeCheck.ok) return scopeCheck

  type RpcResult = { data: string | null; error: { message: string } | null }
  const rpcFn = supabase.rpc.bind(supabase) as unknown as (
    fn: string,
    args: Record<string, unknown>
  ) => Promise<RpcResult>

  const { error: rpcErr } = await rpcFn('apply_deposit_to_session', {
    p_project_id: parsed.data.project_id,
    p_booking_id: parsed.data.booking_id,
    p_amount_cents: parsed.data.amount_cents,
  })

  if (rpcErr) {
    logger.error({ rpcErr, projectId: parsed.data.project_id }, 'applyDepositToSessionAction RPC failed')
    const message = rpcErr.message ?? 'Failed to apply deposit'
    return { ok: false, error: message }
  }

  revalidatePath(`/projects/${parsed.data.project_id}`)
  return { ok: true, data: undefined }
}

const refundDepositInputSchema = z.object({
  project_id: z.string().uuid(),
  amount_cents: z.number().int().positive().max(1_000_000_00, 'Amount exceeds the $1M cap'),
  reason: z.string().min(1, 'Reason is required').max(500),
  transaction_id: z.string().uuid().optional(),
})

export async function refundDepositAction(
  input: z.infer<typeof refundDepositInputSchema>
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }

  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return { ok: false, error: 'Only owners and admins can refund deposits' }
  }

  const parsed = refundDepositInputSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  const supabase = await createClient()

  // Pool balance guard
  const { data: proj, error: projErr } = await supabase
    .from('projects')
    .select('id, deposit_pool_cents, deposit_applied_cents')
    .eq('id', parsed.data.project_id)
    .eq('studio_id', auth.studioId)
    .single()

  if (projErr || !proj) {
    return { ok: false, error: 'Project not found' }
  }

  const poolBalance = Math.max(0, proj.deposit_pool_cents - proj.deposit_applied_cents)
  if (parsed.data.amount_cents > poolBalance) {
    return { ok: false, error: 'Refund exceeds pool balance.' }
  }

  // If transaction_id supplied: route through refund API route (which calls Dodo)
  if (parsed.data.transaction_id) {
    try {
      const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
      const res = await fetch(
        `${appUrl}/api/projects/${parsed.data.project_id}/deposits/${parsed.data.transaction_id}/refund`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          // Server actions run in the same request context; cookies forwarded automatically
          // when called from server. This is an internal server-side call.
          body: JSON.stringify({
            amount_cents: parsed.data.amount_cents,
            reason: parsed.data.reason,
          }),
        }
      )
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        return { ok: false, error: json.error ?? 'Refund failed' }
      }
    } catch (err) {
      logger.error({ err, projectId: parsed.data.project_id }, 'refundDepositAction: API call failed')
      return { ok: false, error: 'Failed to process refund' }
    }
  } else {
    // No external transaction — record via RPC directly (no Dodo refund)
    type RpcResult = { data: string | null; error: { message: string } | null }
    const rpcFn = supabase.rpc.bind(supabase) as unknown as (
      fn: string,
      args: Record<string, unknown>
    ) => Promise<RpcResult>

    const { error: rpcErr } = await rpcFn('refund_project_deposit', {
      p_project_id: parsed.data.project_id,
      p_amount_cents: parsed.data.amount_cents,
      p_external_refund_id: null,
      p_note: parsed.data.reason,
    })

    if (rpcErr) {
      logger.error({ rpcErr, projectId: parsed.data.project_id }, 'refundDepositAction RPC failed')
      return { ok: false, error: 'Failed to record refund' }
    }
  }

  revalidatePath(`/projects/${parsed.data.project_id}`)
  return { ok: true, data: undefined }
}

