export function DepositPoolLedger(rawProps: CombinedProps) {
  // Normalize legacy props → new prop shape
  let projectId: string
  let pool: DepositPoolSummary
  let transactions: ProjectDepositTransactionRow[]
  let sessions: DepositPoolSession[]
  let canManage: boolean
  let compact: boolean
  let onRefresh: (() => void) | undefined

  if (isLegacyProps(rawProps)) {
    const { project, transactions: txs, canAdmin, onRefresh: refresh, compact: c } = rawProps
    projectId = project.id
    pool = {
      paid_cents: project.deposit_pool_cents,
      applied_cents: project.deposit_applied_cents,
      remaining_cents: Math.max(0, project.deposit_pool_cents - project.deposit_applied_cents),
      applies_to_session: null,
    }
    transactions = txs
    sessions = project.sessions ?? []
    canManage = canAdmin
    compact = c ?? false
    onRefresh = refresh
  } else {
    projectId = rawProps.projectId
    pool = rawProps.pool
    transactions = rawProps.transactions
    sessions = rawProps.sessions ?? []
    canManage = rawProps.canManage
    compact = rawProps.compact ?? false
    onRefresh = rawProps.onRefresh
  }

